INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37542,216,'IN_PROGRAM_JEE_MATH_SETS_RELATIONS_FUNCTIONS_002','medium','Let f(x)=2x+3. If f(a)=11, what is a?','3','4','5','7','B','Solve 2a+3=11, so 2a=8 and a=4.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37543,216,'IN_PROGRAM_JEE_MATH_SETS_RELATIONS_FUNCTIONS_003','medium','If n(A)=18, n(B)=15 and n(A ∩ B)=7, what is n(A ∪ B)?','26','33','40','10','A','Use n(A∪B)=n(A)+n(B)-n(A∩B)=18+15-7=26.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37544,216,'IN_PROGRAM_JEE_MATH_SETS_RELATIONS_FUNCTIONS_004','medium','Which relation on the integers is an equivalence relation?','aRb iff a<b','aRb iff a-b is even','aRb iff a+b=1','aRb iff a=2b','B','Having an even difference is reflexive, symmetric and transitive.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37545,216,'IN_PROGRAM_JEE_MATH_SETS_RELATIONS_FUNCTIONS_005','challenge','For f(x)=(x-1)/(x+2), which value is excluded from the domain?','-2','-1','1','2','A','The denominator must be nonzero, so x≠-2.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37546,217,'IN_PROGRAM_JEE_MATH_COMPLEX_QUADRATIC_001','easy','What is i^2?','1','-1','i','-i','B','By definition, i²=-1.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37547,217,'IN_PROGRAM_JEE_MATH_COMPLEX_QUADRATIC_002','medium','If z=3+4i, what is |z|?','3','4','5','7','C','|z|=sqrt(3²+4²)=5.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37548,217,'IN_PROGRAM_JEE_MATH_COMPLEX_QUADRATIC_003','medium','The roots of x²-5x+6=0 are:','1 and 6','2 and 3','-2 and -3','3 and 6','B','x²-5x+6=(x-2)(x-3).',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37549,217,'IN_PROGRAM_JEE_MATH_COMPLEX_QUADRATIC_004','medium','If one root of x²+px+9=0 is 3, what is p?','-6','6','-3','3','A','Substitute x=3: 9+3p+9=0, hence p=-6.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37550,217,'IN_PROGRAM_JEE_MATH_COMPLEX_QUADRATIC_005','challenge','For z=(1+i)/(1-i), z equals:','1','-1','i','-i','C','Multiply numerator and denominator by 1+i: (1+i)²/2=i.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37551,218,'IN_PROGRAM_JEE_MATH_MATRICES_DETERMINANTS_001','easy','What is det([[2,0],[0,3]])?','5','6','0','-6','B','For a diagonal 2×2 matrix, determinant is 2×3=6.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37552,218,'IN_PROGRAM_JEE_MATH_MATRICES_DETERMINANTS_002','medium','If A=[[1,2],[3,4]], what is tr(A)?','4','5','6','10','B','The trace is the sum of diagonal entries: 1+4=5.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37553,218,'IN_PROGRAM_JEE_MATH_MATRICES_DETERMINANTS_003','medium','For A=[[1,2],[2,4]], det(A) is:','0','2','4','8','A','det(A)=1·4-2·2=0.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37554,218,'IN_PROGRAM_JEE_MATH_MATRICES_DETERMINANTS_004','medium','If det(A)=5 for a 2×2 matrix, what is det(3A)?','15','30','45','5','C','For a 2×2 matrix, det(kA)=k²det(A)=9×5=45.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37555,218,'IN_PROGRAM_JEE_MATH_MATRICES_DETERMINANTS_005','challenge','The inverse of [[1,0],[0,2]] is:','[[1,0],[0,1/2]]','[[1,0],[0,2]]','[[2,0],[0,1]]','[[1/2,0],[0,1]]','A','The inverse of a diagonal matrix has reciprocal diagonal entries.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37556,219,'IN_PROGRAM_JEE_MATH_PERMUTATIONS_COMBINATIONS_001','easy','How many ways can 4 distinct books be arranged on a shelf?','4','12','24','16','C','The number of arrangements is 4!=24.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37557,219,'IN_PROGRAM_JEE_MATH_PERMUTATIONS_COMBINATIONS_002','medium','How many ways can 2 students be chosen from 5 students?','10','20','25','5','A','The count is C(5,2)=10.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37558,219,'IN_PROGRAM_JEE_MATH_PERMUTATIONS_COMBINATIONS_003','medium','How many 3-digit numbers can be formed from 1,2,3,4 without repetition?','12','24','64','6','B','Choose and arrange 3 of 4 digits: P(4,3)=4·3·2=24.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37559,219,'IN_PROGRAM_JEE_MATH_PERMUTATIONS_COMBINATIONS_004','medium','How many distinct arrangements does the word LEVEL have?','120','60','30','20','C','LEVEL has 5 letters with L repeated twice and E repeated twice: 5!/(2!2!)=30.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37560,219,'IN_PROGRAM_JEE_MATH_PERMUTATIONS_COMBINATIONS_005','challenge','From 6 men and 4 women, how many 3-person committees contain exactly 2 women?','24','36','60','90','B','Choose 2 of 4 women and 1 of 6 men: C(4,2)C(6,1)=6×6=36.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37561,220,'IN_PROGRAM_JEE_MATH_BINOMIAL_THEOREM_001','easy','In (1+x)^5, the coefficient of x is:','1','5','10','25','B','The coefficient of x is C(5,1)=5.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37562,220,'IN_PROGRAM_JEE_MATH_BINOMIAL_THEOREM_002','medium','The coefficient of x² in (1+x)^6 is:','6','12','15','20','C','The coefficient is C(6,2)=15.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37563,220,'IN_PROGRAM_JEE_MATH_BINOMIAL_THEOREM_003','medium','The middle term coefficient in (1+x)^4 is:','4','6','8','10','B','The middle term is C(4,2)x², with coefficient 6.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37564,220,'IN_PROGRAM_JEE_MATH_BINOMIAL_THEOREM_004','medium','The constant term in (x+1/x)^4 is:','4','6','8','12','B','For x^(4-2r) to be x^0, r=2; coefficient C(4,2)=6.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37565,220,'IN_PROGRAM_JEE_MATH_BINOMIAL_THEOREM_005','challenge','The coefficient of x³ in (1+2x)^5 is:','40','60','80','120','C','Coefficient = C(5,3)·2³ = 10·8 = 80.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
