INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37575,222,'IN_PROGRAM_JEE_MATH_LIMITS_CONTINUITY_DIFFERENTIABILITY_005','challenge','lim(x→1) (x²-1)/(x-1) equals:','0','1','2','Does not exist','C','Factor x²-1=(x-1)(x+1), then limit is 2.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37576,223,'IN_PROGRAM_JEE_MATH_INTEGRAL_CALCULUS_001','easy','∫ 2x dx equals:','x²+C','2x²+C','x+C','2+C','A','The antiderivative of 2x is x²+C.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
