INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37579,223,'IN_PROGRAM_JEE_MATH_INTEGRAL_CALCULUS_004','medium','∫₁² 1/x dx equals:','1','ln 2','2 ln 2','1/2','B','The antiderivative is ln x, giving ln2-ln1=ln2.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(37580,223,'IN_PROGRAM_JEE_MATH_INTEGRAL_CALCULUS_005','challenge','The area under y=x² from x=0 to x=2 is:','4/3','8/3','4','8','B','∫₀²x²dx=[x³/3]₀²=8/3.',1,'jee-rebuild-v1','2026-09-02 07:50:30','2026-09-02 07:50:30');
