INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39041,217,'IN_PROGRAM_JEE_MATH_TEST1_NUM_M1','medium','For x² - 7x + 10 = 0, enter the sum of the two roots.','7','','','','A','For ax²+bx+c=0, sum of roots=-b/a=7.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39042,218,'IN_PROGRAM_JEE_MATH_TEST1_NUM_M2','medium','Enter det([[3,2],[1,4]]).','10','','','','A','det=3×4-2×1=10.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39043,221,'IN_PROGRAM_JEE_MATH_TEST1_NUM_M3','medium','An AP has first term 2 and common difference 3. Enter its 10th term.','29','','','','A','a10=2+9×3=29.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39044,222,'IN_PROGRAM_JEE_MATH_TEST1_NUM_M4','medium','For f(x)=x²+3x, enter f''(2).','7','','','','A','f''(x)=2x+3, so f''(2)=7.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39045,219,'IN_PROGRAM_JEE_MATH_TEST1_NUM_M5','medium','Enter the number of ways to choose 2 objects from 6 distinct objects.','15','','','','A','C(6,2)=15.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39046,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_NUM_P1','medium','A particle has u=5 m/s, a=2 m/s² for 4 s. Enter its final speed in m/s.','13','','','','A','v=u+at=5+2×4=13.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39047,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_NUM_P2','medium','A 6 kg body accelerates at 3 m/s². Enter the net force in newtons.','18','','','','A','F=ma=6×3=18 N.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39048,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_NUM_P3','medium','A 2 kg body moves at 4 m/s. Enter its kinetic energy in joules.','16','','','','A','K=½mv²=½×2×16=16 J.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39049,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_NUM_P4','medium','A 4 Ω resistor has 12 V across it. Enter the current in amperes.','3','','','','A','I=V/R=12/4=3 A.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39050,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_NUM_P5','medium','A convex lens has focal length 15 cm. An object is placed at 2f. Enter the image distance in cm.','30','','','','A','An object at 2f forms its image at 2f=30 cm.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39051,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_NUM_C1','medium','Enter the number of moles in 36 g of H2O. Take molar mass H2O=18 g/mol.','2','','','','A','n=m/M=36/18=2 mol.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39052,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_NUM_C2','medium','A solution has [H+]=1×10^-4 M. Enter its pH.','4','','','','A','pH=-log10[H+]=4.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39053,264,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_NUM_C3','medium','Enter the oxidation state of Mn in KMnO4.','7','','','','A','K is +1 and four O total -8, hence Mn=+7.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39054,258,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_NUM_C4','medium','Enter the number of atoms per body-centered cubic unit cell.','2','','','','A','Corners contribute 1 atom total and body center contributes 1, giving 2.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39055,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_NUM_C5','medium','Enter the coordination number of Co in [Co(NH3)6]3+.','6','','','','A','Six monodentate NH3 ligands are directly attached to Co.',1,'jee-mock-v1','2026-09-02 09:05:10','2026-09-02 09:05:10');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39056,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M1','challenge','If z satisfies z²-(2+i)z+(1+i)=0, then the product of the moduli of its two roots is:','1','√2','2','2√2','B','The product of the roots is 1+i, so the product of their moduli is |1+i|=√2.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39057,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M2','challenge','Let A be a 2×2 real matrix with trace 6 and determinant 8. If the eigenvalues are real, the larger eigenvalue is:','2','3','4','8','C','Eigenvalues satisfy λ²-6λ+8=0, giving 2 and 4.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39058,221,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M3','challenge','For a geometric progression with positive terms, the 2nd, 5th and 8th terms are x, y and z. Which relation must hold?','y=x+z','y²=xz','xz=1','x²=yz','B','The exponents are equally spaced, so the middle term squared equals the product of the outer terms.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39059,222,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M4','challenge','For f(x)=x³-3x, the number of points in [-2,2] at which f''(x)=0 is:','0','1','2','3','C','f''(x)=3x²-3=0 at x=±1.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39060,219,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M5','challenge','The number of 5-digit numbers formed using distinct digits from {1,2,3,4,5,6} and divisible by 5 is:','24','60','120','240','C','The last digit must be 5. The remaining four positions are filled by choosing and arranging 4 of the remaining 5 digits: 5P4=120.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39061,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_SC_M6','challenge','If A is a 3×3 matrix with det(A)=2, then det(3A) equals:','6','18','27','54','D','For a 3×3 matrix, det(kA)=k³det(A)=27×2=54.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39062,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M1','challenge','For z=3+4i, which statements are correct?','|z|=5','z·conjugate(z)=25','1/z=(3-4i)/25','arg(z)=π/4','A','The modulus is 5, z·conjugate(z)=25, and 1/z=(3-4i)/25. The argument is not π/4.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39063,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M2','challenge','For a square matrix A, which statements are always true?','det(Aᵀ)=det(A)','det(AB)=det(A)det(B)','det(A+B)=det(A)+det(B)','If det(A)≠0 then A is invertible','A','Transpose preserves determinant, determinants multiply, and nonzero determinant implies invertibility. Determinant is not additive.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39064,221,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M3','challenge','For an arithmetic progression with first term a and common difference d, which are correct?','aₙ=a+(n-1)d','Sₙ=n[2a+(n-1)d]/2','If d=0 all terms are equal','Sₙ=n(a+d) for all n','A','The standard nth-term and sum formulas hold, and d=0 gives a constant sequence.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39065,222,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M4','challenge','Let f be differentiable at x=a. Which statements must be true?','f is continuous at a','The left and right derivatives at a are equal','f''(a) is finite','f has a local extremum at a','A','Differentiability implies continuity, equality of one-sided derivatives, and a finite derivative; it does not imply an extremum.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39066,219,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M5','challenge','For integers n≥r≥0, which identities are correct?','C(n,r)=C(n,n-r)','r·C(n,r)=n·C(n-1,r-1)','C(n,r)+C(n,r+1)=C(n+1,r+1)','P(n,r)=C(n,r)/r!','A','The first three are standard identities. P(n,r)=C(n,r)r!, not C(n,r)/r!.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39067,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_MS_M6','challenge','For the quadratic x²-5x+6=0, which statements are correct?','Both roots are positive','Sum of roots is 5','Product of roots is 6','The discriminant is negative','A','The roots are 2 and 3, so the first three statements are true and the discriminant is positive.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39068,217,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M1','challenge','If the roots of x²-9x+14=0 are α and β, enter α²+β².','53','','','','A','(α+β)²-2αβ=9²-2×14=53.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39069,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M2','challenge','For A=[[2,1],[3,4]], enter det(A²).','25','','','','A','det(A)=8-3=5 and det(A²)=det(A)²=25.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39070,221,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M3','challenge','An AP has 5th term 18 and 11th term 42. Enter its common difference.','4','','','','A','The difference of the terms is 6d=42-18=24, hence d=4.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39071,222,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M4','challenge','Enter the value of lim(x→0) [sin(5x)/x].','5','','','','A','sin(5x)/(5x)→1, so the limit is 5.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39072,219,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M5','challenge','Enter the number of diagonals in a convex 12-gon.','54','','','','A','The number of diagonals is n(n-3)/2=12×9/2=54.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39073,218,'IN_PROGRAM_JEE_MATH_TEST1_ADV_NUM_M6','challenge','If det(A)=3 for a 2×2 matrix A, enter det(3A⁻¹).','1.3333333333333333','','','','A','det(2A⁻¹)=2² det(A⁻¹)=4/3.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39074,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P1','challenge','A particle moves along x-axis with x=t³-6t²+9t. Its velocity is zero at t=1 s and:','2 s','3 s','4 s','6 s','B','v=3t²-12t+9=3(t-1)(t-3), so the second instant is 3 s.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39075,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P2','challenge','A 5 kg block on a frictionless horizontal surface is pulled by 20 N. If a 3 kg block is attached to it and the same force pulls the pair, the acceleration becomes:','1.5 m/s²','2.5 m/s²','4 m/s²','6.67 m/s²','B','The total mass is 8 kg, so a=20/8=2.5 m/s².',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39076,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P3','challenge','A spring of constant 200 N/m is compressed by 0.10 m. Its stored elastic potential energy is:','0.5 J','1 J','2 J','10 J','B','U=½kx²=0.5×200×0.01=1 J.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39077,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P4','challenge','Two resistors 6 Ω and 3 Ω are connected in parallel across 12 V. The total current drawn is:','2 A','4 A','6 A','8 A','C','Equivalent resistance is 2 Ω, hence I=12/2=6 A.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39078,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P5','challenge','A thin convex lens has focal length 20 cm. An object is placed 60 cm in front of it. The magnitude of image distance is:','15 cm','20 cm','30 cm','60 cm','C','1/f=1/v+1/u in magnitudes gives 1/20=1/v+1/60, hence v=30 cm.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39079,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_SC_P6','challenge','A 2 kg body moving at 6 m/s is brought to rest uniformly over 3 m. The magnitude of the average retarding force is:','6 N','9 N','12 N','18 N','C','Work by the retarding force equals the loss of kinetic energy: F×3=½×2×36=36, so F=12 N.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39080,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P1','challenge','For one-dimensional motion with constant acceleration, which relations are valid?','v=u+at','s=ut+½at²','v²=u²+2as','s=(u+v)t for all such motion','A','The first three are standard equations. Average velocity is (u+v)/2, so s=(u+v)t/2.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39081,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P2','challenge','Which statements about Newton''s laws are correct in an inertial frame?','Net force equals rate of change of momentum','Action and reaction act on different bodies','If net force is zero, momentum is constant','A moving body must have a net force in the direction of motion','A','The first three are correct. Uniform motion needs no net force.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39082,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P3','challenge','Which quantities can be negative?','Work done by a force','Kinetic energy','Potential energy relative to a chosen zero','Power delivered by a force','A','Work, potential energy relative to a reference, and instantaneous power may be negative; kinetic energy is nonnegative.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39083,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P4','challenge','For resistors connected in parallel, which statements are correct?','Potential difference across each branch is the same','Equivalent resistance is less than the smallest branch resistance','Currents in all branches must be equal','Total current is the sum of branch currents','A','Parallel branches share the same voltage, equivalent resistance is smaller than any branch resistance, and currents add.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39084,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P5','challenge','For a real object in front of a concave mirror, which image types are possible as the object position changes?','Real inverted','Virtual erect','Magnified','Diminished','A','A concave mirror can produce all four descriptions depending on object position.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39085,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_MS_P6','challenge','For a metallic conductor obeying Ohm''s law at constant temperature, which statements are correct?','V is proportional to I','Resistance is V/I','Doubling V doubles I','Resistance necessarily doubles when V doubles','A','Ohm''s law gives V=IR with constant R; increasing V changes current, not the resistance under the stated condition.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39086,231,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P1','challenge','A particle starts from rest with constant acceleration 3 m/s². Enter the distance travelled in the 4th second in metres.','10.5','','','','A','Distance in nth second is u+a(n-1/2)=0+3×3.5=10.5 m.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39087,232,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P2','challenge','A 10 kg block has horizontal forces 35 N right and 15 N left. Enter its acceleration in m/s².','2','','','','A','Net force is 20 N, so a=20/10=2 m/s².',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39088,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P3','challenge','A 1000 kg car increases speed from 10 m/s to 20 m/s. Enter the increase in kinetic energy in kJ.','150','','','','A','ΔK=½m(v²-u²)=500(400-100)=150000 J=150 kJ.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39089,241,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P4','challenge','Three 6 Ω resistors are connected in parallel. Enter the equivalent resistance in ohms.','2','','','','A','For three equal resistors R in parallel, Req=R/3=2 Ω.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39090,245,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P5','challenge','A lens has power +5 dioptres. Enter its focal length in centimetres.','20','','','','A','f=1/P=0.2 m=20 cm.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39091,233,'IN_PROGRAM_JEE_PHYSICS_TEST1_ADV_NUM_P6','challenge','A machine does 18 kJ of work in 30 s. Enter its average power in watts.','600','','','','A','P=W/t=18000/30=600 W.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39092,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C1','challenge','How many moles of oxygen atoms are present in 0.5 mol of H2SO4?','0.5','1','2','4','C','Each mole of H2SO4 contains 4 mol of O atoms, so 0.5 mol contains 2 mol.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39093,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C2','challenge','For the equilibrium H2(g)+I2(g) ⇌ 2HI(g), decreasing the volume at constant temperature ideally causes the equilibrium composition to:','shift right','shift left','remain unchanged','form only HI','C','The total number of gaseous moles is the same on both sides, so pressure/volume change does not shift the equilibrium.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39094,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C3','challenge','The coordination number of Co in [Co(NH3)6]3+ is:','3','4','6','9','C','Six monodentate NH3 ligands are directly coordinated to Co.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39095,264,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C4','challenge','Which ion has a d5 configuration?','Fe3+','Cu2+','Zn2+','Sc3+','A','Fe is [Ar]3d6 4s2; Fe3+ is [Ar]3d5.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39096,258,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C5','challenge','The number of atoms effectively present in one face-centered cubic unit cell is:','2','3','4','6','C','Eight corners contribute 1 atom and six faces contribute 3 atoms, total 4.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39097,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_SC_C6','challenge','At 25°C, a solution with [H+]=10^-3 M has pH:','1','2','3','11','C','pH=-log10(10^-3)=3.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39098,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C1','challenge','Which statements about one mole are correct?','It contains Avogadro''s number of specified entities','One mole of ideal gas always occupies 22.4 L at every temperature and pressure','Molar mass in grams is numerically equal to relative molecular mass','0.5 mol contains half Avogadro''s number of entities','A','Avogadro count and molar-mass relations are correct; 22.4 L applies only approximately under specific standard conditions.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39099,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C2','challenge','For a system at chemical equilibrium, which statements are correct?','Forward and reverse reaction rates are equal','Macroscopic concentrations remain constant with time','Both reactions stop','A catalyst changes the equilibrium constant','A','Equilibrium is dynamic: rates are equal and macroscopic concentrations are constant. Reactions continue, and a catalyst does not change K.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39100,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C3','challenge','Which can act as ligands through a lone pair?','NH3','H2O','CN-','Na+','A','NH3, H2O and CN- donate lone pairs; Na+ is not a ligand donor.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39101,264,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C4','challenge','Which are characteristic features often associated with transition-metal ions?','Variable oxidation states','Colored compounds','Complex formation','Only +1 oxidation state','A','Variable oxidation states, color, and complex formation are common transition-metal behavior.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39102,258,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C5','challenge','For an ideal face-centered cubic lattice, which statements are correct?','Atoms per unit cell = 4','Coordination number = 12','Packing efficiency is greater than simple cubic','Each corner atom belongs entirely to one unit cell','A','FCC has 4 atoms per cell, coordination number 12, and high packing efficiency. Corner atoms are shared among eight cells.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39103,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_MS_C6','challenge','For a weak acid HA in water, which changes generally increase its degree of ionization?','Dilution','Adding a strong acid containing H+','Removing H+ from solution','Increasing concentration of HA at fixed temperature','A','Dilution favors ionization of a weak electrolyte, and removing H+ shifts HA ⇌ H+ + A- to the right.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39104,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C1','challenge','Enter the number of moles in 44 g of CO2 (molar mass 44 g/mol).','1','','','','A','n=m/M=44/44=1 mol.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39105,255,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C2','challenge','At 25°C, enter the pOH of a solution whose pH is 9.','5','','','','A','At 25°C, pH+pOH=14, hence pOH=5.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39106,265,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C3','challenge','Enter the oxidation state of Co in [Co(NH3)5Cl]Cl2.','3','','','','A','The complex cation has charge +2. With one coordinated Cl- and neutral NH3, x-1=+2, so x=+3.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39107,264,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C4','challenge','Enter the number of unpaired electrons in a free high-spin Fe3+ ion (3d5).','5','','','','A','A high-spin d5 configuration has one electron in each of the five d orbitals.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39108,258,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C5','challenge','Enter the coordination number of a body-centered cubic lattice.','8','','','','A','Each atom in BCC has eight nearest neighbors.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39109,250,'IN_PROGRAM_JEE_CHEMISTRY_TEST1_ADV_NUM_C6','challenge','Enter the mass in grams of 0.25 mol of NaOH (molar mass 40 g/mol).','10','','','','A','m=nM=0.25×40=10 g.',1,'jee-mock-advanced-v1','2026-09-02 22:09:11','2026-09-02 22:09:11');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39110,217,'IN_PROGRAM_JEE_MATH_MINIA_ADV_M_SC1','challenge','If the roots of x²-6x+k=0 differ by 2, then k is:','5','8','9','10','B','If roots are 3±1, their product is 2×4=8.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39111,218,'IN_PROGRAM_JEE_MATH_MINIA_ADV_M_SC2','challenge','For A=[[1,2],[2,4]], the rank of A is:','0','1','2','4','B','The second row is twice the first and the matrix is nonzero, so rank(A)=1.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39112,222,'IN_PROGRAM_JEE_MATH_MINIA_ADV_M_MS1','challenge','For f(x)=|x|, which statements are correct?','f is continuous at x=0','f is differentiable at x=0','Left derivative at 0 is -1','Right derivative at 0 is 1','A','The function is continuous at 0, but the one-sided derivatives are -1 and +1, so it is not differentiable there.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39113,219,'IN_PROGRAM_JEE_MATH_MINIA_ADV_M_MS2','challenge','Which expressions equal 10?','C(5,2)','C(5,3)','P(5,2)/2','C(10,1)','A','C(5,2)=C(5,3)=10, P(5,2)/2=20/2=10, and C(10,1)=10.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39114,221,'IN_PROGRAM_JEE_MATH_MINIA_ADV_M_N1','challenge','The first three terms of a GP are 2, 6, 18. Enter the sum of its first five terms.','242','','','','A','The common ratio is 3, so S5=2(3^5-1)/(3-1)=242.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39115,231,'IN_PROGRAM_JEE_PHYSICS_MINIA_ADV_P_SC1','challenge','A particle has velocity v=4t-2 (SI units). Its displacement from t=1 s to t=3 s is:','8 m','12 m','16 m','20 m','B','Integrating v from 1 to 3 gives [2t²-2t] from 1 to 3 = 12 m.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39116,241,'IN_PROGRAM_JEE_PHYSICS_MINIA_ADV_P_SC2','challenge','A 4 Ω and a 12 Ω resistor are connected in parallel. Their equivalent resistance is:','2 Ω','3 Ω','4 Ω','8 Ω','B','1/R=1/4+1/12=1/3, hence R=3 Ω.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39117,232,'IN_PROGRAM_JEE_PHYSICS_MINIA_ADV_P_MS1','challenge','A body moves with constant velocity in an inertial frame. Which statements must be true?','Its acceleration is zero','The net external force is zero','Its momentum is constant','No forces at all act on it','A','Constant velocity means zero acceleration, hence zero net force and constant momentum; individual forces may still cancel.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39118,233,'IN_PROGRAM_JEE_PHYSICS_MINIA_ADV_P_MS2','challenge','For a conservative force, which statements are correct?','Work over a closed path is zero','Potential energy can be defined','Work depends only on endpoints','Work must always be positive','A','Conservative-force work is path independent, permits a potential energy, and vanishes over a closed path.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39119,245,'IN_PROGRAM_JEE_PHYSICS_MINIA_ADV_P_N1','challenge','A convex lens of focal length 15 cm forms a real image of an object placed 30 cm from it. Enter the image distance in cm.','30','','','','A','The object is at 2f, so the real image forms at 2f=30 cm.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39120,255,'IN_PROGRAM_JEE_CHEMISTRY_MINIA_ADV_C_SC1','challenge','For N2(g)+3H2(g) ⇌ 2NH3(g), increasing pressure at constant temperature shifts equilibrium:','toward reactants','toward products','nowhere because K changes','randomly','B','The product side has fewer gaseous moles, so higher pressure favors products.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39121,265,'IN_PROGRAM_JEE_CHEMISTRY_MINIA_ADV_C_SC2','challenge','The oxidation state of Fe in [Fe(CN)6]3- is:','+2','+3','+4','+6','B','Let Fe=x. Then x+6(-1)=-3, so x=+3.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39122,250,'IN_PROGRAM_JEE_CHEMISTRY_MINIA_ADV_C_MS1','challenge','Which samples contain exactly 1 mol of the stated particles?','18 g H2O molecules','44 g CO2 molecules','23 g Na atoms (molar mass 23 g/mol)','16 g O2 molecules (molar mass 32 g/mol)','A','The first three masses equal one molar mass; 16 g O2 is only 0.5 mol.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39123,264,'IN_PROGRAM_JEE_CHEMISTRY_MINIA_ADV_C_MS2','challenge','Which statements are commonly true for transition elements or their ions?','They may show variable oxidation states','They often form complexes','Many compounds are colored','All their ions are diamagnetic','A','Variable oxidation states, complex formation, and color are common; many ions are paramagnetic.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39124,258,'IN_PROGRAM_JEE_CHEMISTRY_MINIA_ADV_C_N1','challenge','Enter the number of atoms effectively present in a body-centered cubic unit cell.','2','','','','A','Eight corner atoms contribute 1 atom in total and the body-center contributes 1, giving 2.',1,'jee-mock-advanced-v1','2026-09-02 22:09:25','2026-09-02 22:09:25');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39125,277,'IN_PROGRAM_NEET_PHYSICS_KINEMATICS_001','easy','A car moves with constant speed 20 m/s for 5 s. What distance does it cover?','4 m','25 m','100 m','400 m','C','For uniform motion, distance = speed × time = 20 × 5 = 100 m.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39126,277,'IN_PROGRAM_NEET_PHYSICS_KINEMATICS_002','easy','The slope of a displacement-time graph represents:','Acceleration','Velocity','Force','Momentum','B','The rate of change of displacement with time is velocity.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39127,277,'IN_PROGRAM_NEET_PHYSICS_KINEMATICS_003','medium','An object starts from rest and accelerates uniformly at 2 m/s² for 4 s. Its final speed is:','2 m/s','4 m/s','8 m/s','16 m/s','C','Using v = u + at, v = 0 + 2 × 4 = 8 m/s.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39128,277,'IN_PROGRAM_NEET_PHYSICS_KINEMATICS_004','medium','A projectile is launched horizontally from a height. Neglecting air resistance, its horizontal acceleration is:','g','g/2','Zero','Dependent on speed','C','Gravity acts vertically, so horizontal acceleration is zero.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39129,277,'IN_PROGRAM_NEET_PHYSICS_KINEMATICS_005','medium','For uniform circular motion, which quantity continuously changes?','Speed only','Velocity direction','Mass','Time period','B','The speed may remain constant, but the direction of velocity continuously changes.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39130,296,'IN_PROGRAM_NEET_CHEMISTRY_SOME_BASIC_CONCEPTS_CHEMISTRY_001','easy','One mole of any substance contains approximately:','3.011 × 10²³ entities','6.022 × 10²³ entities','9.8 × 10²³ entities','1.602 × 10⁻¹⁹ entities','B','One mole contains Avogadro''s number, approximately 6.022 × 10²³ entities.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39131,296,'IN_PROGRAM_NEET_CHEMISTRY_SOME_BASIC_CONCEPTS_CHEMISTRY_002','easy','The molar mass of O₂ is approximately:','16 g/mol','18 g/mol','32 g/mol','64 g/mol','C','An oxygen atom is about 16 u, so O₂ has molar mass about 32 g/mol.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39132,296,'IN_PROGRAM_NEET_CHEMISTRY_SOME_BASIC_CONCEPTS_CHEMISTRY_003','medium','How many moles are present in 18 g of water (H₂O), whose molar mass is 18 g/mol?','0.5 mol','1 mol','2 mol','18 mol','B','Moles = mass / molar mass = 18 / 18 = 1 mol.',1,'neet-starter-v1','2026-09-04 18:59:46','2026-09-04 18:59:46');
