INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39143,276,'IN_PROGRAM_NEET_PHYSICS_PHYSICS_AND_MEASUREMENT_004','medium','The dimensional formula of energy is:','MLT^-2','ML^2T^-2','ML^-1T^-2','M^0L^2T^-1','B','Energy = force × distance, so dimensions are ML^2T^-2.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
