INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39153,278,'IN_PROGRAM_NEET_PHYSICS_LAWS_OF_MOTION_004','medium','A 10 kg block on a horizontal surface has coefficient of friction 0.2. Taking g=10 m/s², limiting friction is:','2 N','20 N','50 N','100 N','B','f=μN=0.2×100=20 N.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39154,278,'IN_PROGRAM_NEET_PHYSICS_LAWS_OF_MOTION_005','challenge','Two blocks of 2 kg and 3 kg are pulled together by 10 N on a frictionless surface. Their common acceleration is:','1 m/s²','2 m/s²','3 m/s²','5 m/s²','B','Total mass=5 kg, so a=10/5=2 m/s².',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39155,279,'IN_PROGRAM_NEET_PHYSICS_WORK_ENERGY_POWER_001','easy','Work done by a constant force F along displacement s in the same direction is:','F/s','Fs','F+s','s/F','B','W=Fs cos0°=Fs.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
