INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39157,279,'IN_PROGRAM_NEET_PHYSICS_WORK_ENERGY_POWER_003','medium','A 10 N force moves an object 5 m in its direction. Work done is:','2 J','15 J','50 J','500 J','C','W=Fs=10×5=50 J.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39158,279,'IN_PROGRAM_NEET_PHYSICS_WORK_ENERGY_POWER_004','medium','Power is defined as:','work × time','work/time','force/time','energy × distance','B','Power is the rate of doing work.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39159,279,'IN_PROGRAM_NEET_PHYSICS_WORK_ENERGY_POWER_005','challenge','A spring of constant 200 N/m is compressed by 0.10 m. Stored energy is:','0.5 J','1 J','2 J','10 J','B','U=1/2 kx²=0.5×200×0.01=1 J.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39160,280,'IN_PROGRAM_NEET_PHYSICS_ROTATIONAL_MOTION_001','easy','The rotational analogue of mass is:','torque','moment of inertia','angular momentum','angular speed','B','Moment of inertia measures resistance to angular acceleration.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39161,280,'IN_PROGRAM_NEET_PHYSICS_ROTATIONAL_MOTION_002','medium','Torque magnitude is given by:','rF cosθ','rF sinθ','F/r','r/F','B','τ=r×F has magnitude rF sinθ.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
INSERT INTO "education_questions" ("id","subtopic_id","question_key","difficulty","question_text","choice_a","choice_b","choice_c","choice_d","correct_choice","explanation","active","source_type","created_at","updated_at") VALUES(39162,280,'IN_PROGRAM_NEET_PHYSICS_ROTATIONAL_MOTION_003','medium','For a rigid body rotating about a fixed axis, angular momentum is:','I/ω','Iω','τ/ω','mω','B','L=Iω.',1,'neet-shared-concept-v1','2026-09-04 18:59:52','2026-09-04 18:59:52');
