PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE shops (
  code TEXT PRIMARY KEY
    CHECK(length(code) = 4),

  name TEXT NOT NULL,
  owner_name TEXT NOT NULL,

  phone_number TEXT NOT NULL,
  whatsapp_number TEXT,
  email_address TEXT,

  address_line TEXT NOT NULL,
  city TEXT NOT NULL,
  state TEXT NOT NULL,
  postal_code TEXT NOT NULL,

  status TEXT NOT NULL DEFAULT 'active'
    CHECK(status IN ('pending', 'active', 'suspended')),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, latitude REAL
CHECK (
  latitude IS NULL OR
  (latitude >= -90 AND latitude <= 90)
), longitude REAL
CHECK (
  longitude IS NULL OR
  (longitude >= -180 AND longitude <= 180)
), state_code TEXT);
CREATE TABLE services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_code TEXT NOT NULL UNIQUE,
  service_type TEXT NOT NULL DEFAULT 'system'
    CHECK(service_type IN ('system', 'custom')),

  category TEXT NOT NULL,
  sub_category TEXT,

  name TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  color TEXT,

  workflow_type TEXT NOT NULL DEFAULT 'generic'
    CHECK(
      workflow_type IN (
        'print',
        'upload',
        'assistance',
        'appointment',
        'payment',
        'generic'
      )
    ),

  /*
   * Custom services can belong to one shop.
   * System services leave owner_shop_code NULL.
   */
  owner_shop_code TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK(enabled IN (0, 1)),

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, homepage_order INTEGER
  CHECK (
    homepage_order IS NULL OR
    homepage_order >= 0
  ),

  FOREIGN KEY(owner_shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE shop_services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  enabled INTEGER NOT NULL DEFAULT 0
    CHECK(enabled IN (0, 1)),

  display_name TEXT,
  description_override TEXT,
  icon_override TEXT,
  color_override TEXT,

  price_type TEXT NOT NULL DEFAULT 'contact'
    CHECK(
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  price_amount_paise INTEGER
    CHECK(
      price_amount_paise IS NULL OR
      price_amount_paise >= 0
    ),

  price_note TEXT,

  sort_order INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, featured INTEGER NOT NULL DEFAULT 0,

  UNIQUE(shop_code, service_id),

  FOREIGN KEY(shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY(service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE admin_login_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  code_hash TEXT NOT NULL,

  request_ip TEXT,

  expires_at TEXT NOT NULL,
  used_at TEXT,

  attempt_count INTEGER NOT NULL DEFAULT 0,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  email TEXT NOT NULL,
  session_hash TEXT NOT NULL UNIQUE,

  expires_at TEXT NOT NULL,
  revoked_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE print_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  order_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,

  customer_name TEXT NOT NULL,
  phone_number TEXT NOT NULL,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  estimated_pages INTEGER NOT NULL DEFAULT 1,
  copies INTEGER NOT NULL DEFAULT 1,

  color_mode TEXT NOT NULL,
  print_sides TEXT NOT NULL,
  paper_size TEXT NOT NULL,

  instructions TEXT,

  estimated_amount_rupees INTEGER,

  status TEXT NOT NULL DEFAULT 'submitted',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
);
CREATE TABLE print_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  print_request_id INTEGER NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT,
  file_size INTEGER NOT NULL,

  storage_key TEXT,
  storage_status TEXT NOT NULL DEFAULT 'pending',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (print_request_id)
    REFERENCES print_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE system_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE service_sections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  label TEXT NOT NULL,

  description TEXT,

  visibility TEXT NOT NULL DEFAULT 'visible'
    CHECK (
      visibility IN (
        'visible',
        'hidden'
      )
    ),

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE (
    service_id,
    section_key
  )
);
CREATE TABLE service_fields (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  section_id INTEGER NOT NULL,

  field_key TEXT NOT NULL,
  label TEXT NOT NULL,

  field_type TEXT NOT NULL
    CHECK (
      field_type IN (
        'text',
        'textarea',
        'number',
        'email',
        'tel',
        'date',
        'select',
        'radio',
        'checkbox',
        'checkbox-group',
        'file'
      )
    ),

  requirement TEXT NOT NULL DEFAULT 'optional'
    CHECK (
      requirement IN (
        'mandatory',
        'optional',
        'hidden'
      )
    ),

  placeholder TEXT,
  help_text TEXT,

  default_value TEXT,

  options_json TEXT,
  validation_json TEXT,

  email_label TEXT,

  include_in_shop_email INTEGER NOT NULL DEFAULT 1,
  include_in_customer_email INTEGER NOT NULL DEFAULT 1,
  include_in_request_view INTEGER NOT NULL DEFAULT 1,

  sort_order INTEGER NOT NULL DEFAULT 10,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (section_id)
    REFERENCES service_sections(id)
    ON DELETE CASCADE,

  UNIQUE (
    section_id,
    field_key
  )
);
CREATE TABLE service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  request_number TEXT NOT NULL UNIQUE,

  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,

  customer_name TEXT,
  phone_number TEXT,
  email_address TEXT,
  whatsapp_number TEXT,
  whatsapp_consent INTEGER NOT NULL DEFAULT 0,

  status TEXT NOT NULL DEFAULT 'submitted',

  details_json TEXT NOT NULL DEFAULT '{}',

  estimated_amount_paise INTEGER,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  FOREIGN KEY (shop_code)
    REFERENCES shops(code),

  FOREIGN KEY (service_id)
    REFERENCES services(id)
);
CREATE TABLE service_request_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_request_id INTEGER NOT NULL,

  section_key TEXT NOT NULL,
  field_key TEXT NOT NULL,

  original_file_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,

  storage_key TEXT NOT NULL UNIQUE,
  storage_status TEXT NOT NULL DEFAULT 'stored',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_request_id)
    REFERENCES service_requests(id)
    ON DELETE CASCADE
);
CREATE TABLE service_market_prices (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  service_id INTEGER NOT NULL,

  country_code TEXT NOT NULL,
  currency_code TEXT NOT NULL,

  price_type TEXT NOT NULL DEFAULT 'starting_at'
    CHECK (
      price_type IN (
        'fixed',
        'starting_at',
        'per_page',
        'quote',
        'free',
        'contact'
      )
    ),

  amount_minor INTEGER
    CHECK (
      amount_minor IS NULL OR
      amount_minor >= 0
    ),

  price_note TEXT,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK (enabled IN (0, 1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE,

  UNIQUE(service_id, country_code)
);
CREATE TABLE daily_puzzles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_date TEXT NOT NULL,
  puzzle_number INTEGER NOT NULL,

  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  board_size INTEGER NOT NULL,
  max_moves INTEGER NOT NULL,
  mystery_count INTEGER NOT NULL,

  /*
   * What the player receives.
   */
  start_board_json TEXT NOT NULL,

  /*
   * Admin/debug only.
   */
  solved_board_json TEXT NOT NULL,

  /*
   * Admin/hint-engine only.
   */
  solution_moves_json TEXT NOT NULL,

  /*
   * Server-side reveal sequence.
   */
  mystery_reveal_order_json TEXT NOT NULL,

  verified INTEGER
    NOT NULL
    DEFAULT 0,

  status TEXT
    NOT NULL
    DEFAULT 'draft'
    CHECK (
      status IN (
        'draft',
        'published',
        'retired'
      )
    ),

  created_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT
    NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_date,
    stage
  ),

  UNIQUE (
    puzzle_number,
    stage
  )
);
CREATE TABLE puzzle_winners (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,

  name TEXT NOT NULL,
  email TEXT NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    puzzle_number,
    email
  )
);
CREATE TABLE featured_promotions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  source_type TEXT NOT NULL
    CHECK (
      source_type IN (
        'gyan',
        'groupon',
        'woot',
        'affiliate',
        'default'
      )
    ),

  title TEXT NOT NULL,
  description TEXT,

  icon TEXT,
  image_url TEXT,

  cta_label TEXT NOT NULL DEFAULT 'View',

  target_url TEXT,

  service_code TEXT,
  shop_code TEXT,

  latitude REAL,
  longitude REAL,
  radius_km REAL,

  starts_at TEXT,
  ends_at TEXT,

  priority INTEGER NOT NULL DEFAULT 0,

  enabled INTEGER NOT NULL DEFAULT 1,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, offer_text TEXT, discount_percent REAL);
CREATE TABLE advertisement_submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification'
    CHECK (
      status IN (
        'pending_email_verification',
        'pending_review',
        'approved',
        'rejected'
      )
    ),

  business_name TEXT NOT NULL,
  service_name TEXT NOT NULL,

  offer_text TEXT,
  discount_percent REAL,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  service_radius_km REAL NOT NULL,

  phone TEXT NOT NULL,
  email TEXT NOT NULL,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,
  approved_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, admin_review_token_hash TEXT, admin_review_expires_at TEXT, duration_days INTEGER NOT NULL DEFAULT 7, description TEXT, featured_promotion_id INTEGER, delete_token_hash TEXT, delete_token_expires_at TEXT, deleted_at TEXT, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE local_service_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  status TEXT NOT NULL DEFAULT 'pending_email_verification',

  service_name TEXT NOT NULL,

  details TEXT,

  latitude REAL NOT NULL,
  longitude REAL NOT NULL,

  search_radius_km REAL NOT NULL,

  email TEXT NOT NULL,
  phone TEXT,

  preferred_time TEXT,

  verification_token_hash TEXT,
  verification_expires_at TEXT,

  email_verified_at TEXT,

  assigned_shop_code TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, city TEXT, region TEXT, region_code TEXT, country_code TEXT, postal_code TEXT);
CREATE TABLE daily_analytics (
  analytics_date TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  latitude REAL,
  longitude REAL,
  unique_visitors INTEGER NOT NULL DEFAULT 0,
  visits INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, country_code, region, city)
);
CREATE TABLE daily_analytics_visitors (
  analytics_date TEXT NOT NULL,
  visitor_hash TEXT NOT NULL,
  country_code TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (analytics_date, visitor_hash)
);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at TEXT, last_city TEXT, last_region TEXT, last_region_code TEXT, last_country_code TEXT, last_postal_code TEXT, last_location_at TEXT);
CREATE TABLE auth_magic_links (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, return_to TEXT, return_path TEXT);
CREATE TABLE user_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE chat_threads (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL UNIQUE,
  customer_user_id INTEGER,
  shop_code TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (request_id) REFERENCES service_requests(id),
  FOREIGN KEY (customer_user_id) REFERENCES users(id)
);
CREATE TABLE chat_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  thread_id INTEGER NOT NULL,
  sender_type TEXT NOT NULL,
  sender_user_id INTEGER,
  sender_shop_code TEXT,
  message TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (thread_id) REFERENCES chat_threads(id),
  FOREIGN KEY (sender_user_id) REFERENCES users(id)
);
CREATE TABLE offline_shop_codes (
  code TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'reserved'
    CHECK (status IN ('reserved','claimed')),
  batch_code TEXT NOT NULL,
  claimed_shop_code TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  claimed_at TEXT,
  CHECK (length(code)=4),
  CHECK (substr(code,3,1)='R')
);
CREATE TABLE shop_featured_services (
  shop_code TEXT NOT NULL,
  service_id INTEGER NOT NULL,
  featured_order INTEGER NOT NULL
    CHECK (featured_order BETWEEN 1 AND 3),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (shop_code, service_id),
  UNIQUE (shop_code, featured_order),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE,

  FOREIGN KEY (service_id)
    REFERENCES services(id)
    ON DELETE CASCADE
);
CREATE TABLE puzzle_results (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  result_id TEXT NOT NULL,

  puzzle_number INTEGER NOT NULL,
  puzzle_date TEXT NOT NULL,
  stage TEXT NOT NULL
    CHECK (
      stage IN (
        '5x5',
        '7x7'
      )
    ),

  gq_score INTEGER NOT NULL,
  moves_used INTEGER NOT NULL,

  icons_json TEXT NOT NULL
    DEFAULT '[]',

  skill_stats_json TEXT NOT NULL
    DEFAULT '{}',

  name TEXT,
  email TEXT,

  claimed INTEGER NOT NULL
    DEFAULT 0
    CHECK (
      claimed IN (
        0,
        1
      )
    ),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  UNIQUE (
    puzzle_number,
    stage,
    result_id
  )
);
CREATE TABLE anonymous_request_usage (
  shop_code TEXT NOT NULL,
  usage_date TEXT NOT NULL,
  request_count INTEGER NOT NULL DEFAULT 0
    CHECK (request_count >= 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    shop_code,
    usage_date
  ),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE request_guard_alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  shop_code TEXT NOT NULL,
  alert_key TEXT NOT NULL,
  alert_scope TEXT NOT NULL
    CHECK (
      alert_scope IN (
        'day',
        'month'
      )
    ),
  period_key TEXT NOT NULL,
  request_count INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (
    shop_code,
    alert_key,
    period_key
  ),

  FOREIGN KEY (shop_code)
    REFERENCES shops(code)
    ON DELETE CASCADE
);
CREATE TABLE puzzle_guest_names (
  puzzle_number INTEGER NOT NULL,
  result_id TEXT NOT NULL,
  guest_name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (puzzle_number, result_id),
  UNIQUE (puzzle_number, guest_name)
);
CREATE TABLE student_invite_codes (
  code TEXT PRIMARY KEY,

  country_code TEXT NOT NULL,

  print_format TEXT NOT NULL
    CHECK (
      print_format IN (
        'A5',
        'A6',
        'A7',
        'A8',
        'CREDIT_CARD',
        'BUSINESS_CARD'
      )
    ),

  orientation TEXT NOT NULL
    CHECK (
      orientation IN (
        'portrait',
        'landscape'
      )
    ),

  range_start TEXT NOT NULL,
  range_end TEXT NOT NULL,

  status TEXT NOT NULL
    DEFAULT 'active'
    CHECK (
      status IN (
        'active',
        'disabled'
      )
    ),

  scan_count INTEGER NOT NULL
    DEFAULT 0,

  registration_count INTEGER NOT NULL
    DEFAULT 0,

  first_scanned_at TEXT,
  last_scanned_at TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  CHECK (
    length(code) = 4
  )
);
CREATE TABLE education_country_settings (
  country_code TEXT PRIMARY KEY
    CHECK (country_code IN ('US', 'IN')),

  prek12_enabled INTEGER NOT NULL DEFAULT 1
    CHECK (prek12_enabled IN (0, 1)),

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_programs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  country_code TEXT NOT NULL
    CHECK (country_code IN ('US', 'IN')),

  program_code TEXT NOT NULL,
  program_name TEXT NOT NULL,

  enabled INTEGER NOT NULL DEFAULT 1
    CHECK (enabled IN (0, 1)),

  is_custom INTEGER NOT NULL DEFAULT 0
    CHECK (is_custom IN (0, 1)),

  sort_order INTEGER NOT NULL DEFAULT 100,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  UNIQUE(country_code, program_code),

  FOREIGN KEY(country_code)
    REFERENCES education_country_settings(country_code)
    ON DELETE CASCADE
);
CREATE TABLE education_subjects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  country_code TEXT NOT NULL,
  grade_code TEXT NOT NULL,
  subject_code TEXT NOT NULL,
  subject_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(country_code, grade_code, subject_code)
);
CREATE TABLE education_topics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  subject_id INTEGER NOT NULL,
  topic_code TEXT NOT NULL,
  topic_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(subject_id, topic_code),
  FOREIGN KEY(subject_id)
    REFERENCES education_subjects(id)
    ON DELETE CASCADE
);
CREATE TABLE education_subtopics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  topic_id INTEGER NOT NULL,
  subtopic_code TEXT NOT NULL,
  subtopic_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(topic_id, subtopic_code),
  FOREIGN KEY(topic_id)
    REFERENCES education_topics(id)
    ON DELETE CASCADE
);
CREATE TABLE education_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  subtopic_id INTEGER NOT NULL,
  question_key TEXT NOT NULL UNIQUE,
  difficulty TEXT NOT NULL
    CHECK (difficulty IN ('easy','medium','challenge')),
  question_text TEXT NOT NULL,
  choice_a TEXT NOT NULL,
  choice_b TEXT NOT NULL,
  choice_c TEXT NOT NULL,
  choice_d TEXT NOT NULL,
  correct_choice TEXT NOT NULL
    CHECK (correct_choice IN ('A','B','C','D')),
  explanation TEXT NOT NULL DEFAULT '',
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  source_type TEXT NOT NULL DEFAULT 'generated',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(subtopic_id)
    REFERENCES education_subtopics(id)
    ON DELETE CASCADE
);
CREATE TABLE education_students (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_code TEXT NOT NULL UNIQUE,
  student_name TEXT NOT NULL,

  email TEXT NOT NULL,
  user_id INTEGER,

  country_code TEXT NOT NULL,
  grade_code TEXT NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, gyan_account_id INTEGER,

  FOREIGN KEY(user_id)
    REFERENCES users(id)
    ON DELETE SET NULL
);
CREATE TABLE education_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT NOT NULL,

  question_count INTEGER NOT NULL,
  correct_count INTEGER NOT NULL,

  score_percent INTEGER NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_attempt_answers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,

  selected_choice TEXT NOT NULL
    CHECK (selected_choice IN ('A','B','C','D')),

  correct INTEGER NOT NULL
    CHECK (correct IN (0,1)),

  FOREIGN KEY(attempt_id)
    REFERENCES education_attempts(id)
    ON DELETE CASCADE,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT,

  UNIQUE(attempt_id, question_id)
);
CREATE TABLE education_topic_mastery (
  student_id INTEGER NOT NULL,
  subject_code TEXT NOT NULL,
  topic_code TEXT NOT NULL,

  attempts INTEGER NOT NULL DEFAULT 0,
  questions_answered INTEGER NOT NULL DEFAULT 0,
  correct_answers INTEGER NOT NULL DEFAULT 0,

  score_percent INTEGER NOT NULL DEFAULT 0,

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY(
    student_id,
    subject_code,
    topic_code
  ),

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_little_questions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  skill_code TEXT NOT NULL,
  level INTEGER NOT NULL DEFAULT 1,

  prompt_text TEXT NOT NULL,

  question_type TEXT NOT NULL
    CHECK (
      question_type IN (
        'tap',
        'speak'
      )
    ),

  option_a TEXT,
  option_b TEXT,
  option_c TEXT,

  correct_option TEXT
    CHECK (
      correct_option IS NULL OR
      correct_option IN ('A','B','C')
    ),

  accepted_words TEXT,

  active INTEGER NOT NULL DEFAULT 1
    CHECK (active IN (0,1)),

  sort_order INTEGER NOT NULL DEFAULT 100,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, topic_code TEXT, topic_name TEXT, subtopic_code TEXT, subtopic_name TEXT, icon_hint TEXT, visual_type TEXT, visual_object TEXT, option_a_scale TEXT, option_b_scale TEXT, option_c_scale TEXT,

  UNIQUE(
    skill_code,
    level,
    prompt_text,
    option_a,
    option_b,
    option_c
  )
);
CREATE TABLE education_child_words (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER NOT NULL,

  word TEXT NOT NULL,
  normalized_word TEXT NOT NULL,

  status TEXT NOT NULL
    CHECK (
      status IN (
        'emerging',
        'independent'
      )
    ),

  first_observed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  first_independent_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,

  UNIQUE(
    student_id,
    normalized_word
  )
);
CREATE TABLE education_little_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  student_id INTEGER,

  question_id INTEGER NOT NULL,

  response_type TEXT NOT NULL
    CHECK (
      response_type IN (
        'tap',
        'speech',
        'parent'
      )
    ),

  response_value TEXT,

  correct INTEGER NOT NULL
    CHECK (correct IN (0,1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE SET NULL,

  FOREIGN KEY(question_id)
    REFERENCES education_little_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE calendar_access_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  slug TEXT NOT NULL UNIQUE,
  gyan_name TEXT NOT NULL UNIQUE,
  access_code TEXT NOT NULL UNIQUE,

  qr_token_hash TEXT UNIQUE,

  duration_months INTEGER NOT NULL
    CHECK (
      duration_months IN (
        1,
        3,
        6,
        12
      )
    ),

  welcome_gems INTEGER NOT NULL DEFAULT 0,

  artwork_key TEXT NOT NULL DEFAULT 'GODDESS'
    CHECK (
      artwork_key IN (
        'GODDESS',
        'EDUCATION',
        'SCENIC'
      )
    ),

  status TEXT NOT NULL DEFAULT 'GENERATED'
    CHECK (
      status IN (
        'GENERATED',
        'PRINTED',
        'GUEST_ACTIVE',
        'CLAIMED',
        'EXPIRED'
      )
    ),

  email TEXT,

  generated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  printed_at TEXT,

  guest_started_at TEXT,
  guest_expires_at TEXT,

  claimed_at TEXT,
  expires_at TEXT,

  source TEXT NOT NULL DEFAULT 'CALENDAR',
  created_by_email TEXT
);
CREATE TABLE calendar_guest_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  token_hash TEXT NOT NULL UNIQUE,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at TEXT NOT NULL,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE
);
CREATE TABLE gem_transactions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  amount INTEGER NOT NULL,

  reason TEXT NOT NULL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE,

  UNIQUE (
    calendar_access_id,
    reason
  )
);
CREATE TABLE gyan_lost_found_profiles (
  safety_resource_id INTEGER PRIMARY KEY,

  owner_deliver_at TEXT,
  owner_contact TEXT,
  owner_message TEXT,

  finder_found_at TEXT,
  finder_will_deliver_at TEXT,
  finder_message TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, support_requested INTEGER NOT NULL
DEFAULT 0
CHECK (
  support_requested IN (
    0,
    1
  )
),

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_lost_found_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  sender_role TEXT NOT NULL
    CHECK (
      sender_role IN (
        'FINDER',
        'OWNER',
        'SUPPORT'
      )
    ),

  message TEXT NOT NULL,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_emergency_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  message TEXT NOT NULL,

  contact TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_recovery_emails (
  calendar_access_id INTEGER PRIMARY KEY,

  email TEXT NOT NULL,

  verified INTEGER NOT NULL
    DEFAULT 0
    CHECK (verified IN (0, 1)),

  verification_token_hash TEXT,

  verification_expires_at TEXT,

  verified_at TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_emergency_profiles (
  safety_resource_id INTEGER PRIMARY KEY,

  emergency_message TEXT,
  primary_contact TEXT,
  secondary_contact TEXT,
  medical_notes TEXT,
  meeting_place TEXT,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (
    safety_resource_id
  )
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_accounts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  access_code TEXT,
  email TEXT,
  registered INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, created_city TEXT, created_region TEXT, created_region_code TEXT, created_country TEXT, created_country_code TEXT, created_timezone TEXT, created_device_type TEXT, created_os TEXT, created_os_version TEXT, created_browser TEXT, created_browser_version TEXT, created_screen_width INTEGER, created_screen_height INTEGER, created_viewport_width INTEGER, created_viewport_height INTEGER, created_touch INTEGER NOT NULL DEFAULT 0, created_language TEXT, created_languages TEXT, created_platform TEXT, created_referrer TEXT, created_utm_source TEXT, created_utm_medium TEXT, created_utm_campaign TEXT);
CREATE TABLE gyan_browser_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL,
  secret_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id) REFERENCES gyan_accounts(id) ON DELETE CASCADE
);
CREATE TABLE gyan_account_aliases (
  alias_code TEXT PRIMARY KEY,
  account_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id) REFERENCES gyan_accounts(id) ON DELETE CASCADE
);
CREATE TABLE gyan_account_email_verifications (
  account_id INTEGER PRIMARY KEY,
  email TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  verified_at TEXT,
  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "gyan_safety_resources" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  calendar_access_id INTEGER NOT NULL,

  resource_type TEXT NOT NULL
    CHECK (
      resource_type IN (
        'MESSAGE',
        'CERTIFICATE',
        'LOST_FOUND',
        'EMERGENCY',
        'HELP'
      )
    ),

  public_token TEXT NOT NULL UNIQUE,

  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (
      status IN (
        'ACTIVE',
        'REVOKED'
      )
    ),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  revoked_at TEXT,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE,

  UNIQUE (
    calendar_access_id,
    resource_type
  )
);
CREATE TABLE gyan_account_calendar_links (
  gyan_account_id INTEGER NOT NULL UNIQUE,

  calendar_access_id INTEGER NOT NULL UNIQUE,

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (gyan_account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE CASCADE,

  FOREIGN KEY (calendar_access_id)
    REFERENCES calendar_access_codes(id)
    ON DELETE CASCADE
);
CREATE TABLE gyan_winks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  safety_resource_id INTEGER NOT NULL,

  wink_token TEXT NOT NULL UNIQUE,

  kind TEXT NOT NULL DEFAULT '😉',

  message TEXT NOT NULL,

  recipient_query TEXT,

  add_friend INTEGER NOT NULL DEFAULT 0
    CHECK (add_friend IN (0, 1)),

  created_at TEXT NOT NULL
    DEFAULT CURRENT_TIMESTAMP, sender_account_id INTEGER
REFERENCES gyan_accounts(id)
ON DELETE SET NULL, recipient_account_id INTEGER
REFERENCES gyan_accounts(id)
ON DELETE SET NULL, parent_wink_id INTEGER
REFERENCES gyan_winks(id)
ON DELETE SET NULL, read_at TEXT, expires_at TEXT,

  FOREIGN KEY (safety_resource_id)
    REFERENCES gyan_safety_resources(id)
    ON DELETE CASCADE
);
CREATE TABLE class_teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  display_name TEXT NOT NULL,
  education TEXT NOT NULL DEFAULT '',
  experience TEXT NOT NULL DEFAULT '',
  level TEXT NOT NULL CHECK (level IN ('BRONZE','SILVER','GOLD')),
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE class_offerings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL CHECK (category IN ('IIT-JEE','NEET')),
  subject TEXT NOT NULL,
  topic TEXT NOT NULL,
  teacher_id INTEGER NOT NULL,
  class_type TEXT NOT NULL CHECK (class_type IN ('DEMO','ACTUAL')),
  weekday INTEGER NOT NULL CHECK (weekday BETWEEN 1 AND 7),
  start_ist TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL CHECK (duration_minutes IN (30,60)),
  program_start_date TEXT NOT NULL,
  program_end_date TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (teacher_id) REFERENCES class_teachers(id)
);
CREATE TABLE class_registrations (
  id TEXT PRIMARY KEY,
  offering_id INTEGER NOT NULL,
  occurrence_date TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'REGISTERED',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (offering_id) REFERENCES class_offerings(id)
);
CREATE TABLE education_question_metadata (
  question_id INTEGER PRIMARY KEY,
  exam_level TEXT NOT NULL DEFAULT 'BOTH'
    CHECK (exam_level IN ('MAIN','ADVANCED','BOTH')),
  question_format TEXT NOT NULL DEFAULT 'SINGLE_CHOICE'
    CHECK (question_format IN (
      'SINGLE_CHOICE',
      'NUMERICAL',
      'MULTI_SELECT',
      'INTEGER',
      'MATCHING',
      'COMPREHENSION'
    )),
  syllabus_version TEXT NOT NULL DEFAULT 'JEE_2026',
  quality_status TEXT NOT NULL DEFAULT 'DRAFT'
    CHECK (quality_status IN ('DRAFT','REVIEWED','PUBLISHED','RETIRED')),
  archetype_code TEXT,
  source_note TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_mock_tests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  program_code TEXT NOT NULL,
  test_kind TEXT NOT NULL
    CHECK (test_kind IN ('FULL','MINI')),
  test_code TEXT NOT NULL,
  test_name TEXT NOT NULL,
  exam_level TEXT NOT NULL
    CHECK (exam_level IN ('MAIN','ADVANCED','NEET')),
  version INTEGER NOT NULL DEFAULT 1,
  access_mode TEXT NOT NULL DEFAULT 'LOCKED'
    CHECK (access_mode IN ('OPEN','CODE','LOCKED')),
  published INTEGER NOT NULL DEFAULT 0
    CHECK (published IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (
    program_code,
    test_kind,
    test_code,
    exam_level,
    version
  )
);
CREATE TABLE education_mock_test_questions (
  mock_test_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  question_order INTEGER NOT NULL,
  section_code TEXT,
  marks_correct REAL,
  marks_incorrect REAL,
  marks_unanswered REAL NOT NULL DEFAULT 0,
  PRIMARY KEY (mock_test_id, question_order),
  UNIQUE (mock_test_id, question_id),
  FOREIGN KEY (mock_test_id)
    REFERENCES education_mock_tests(id)
    ON DELETE CASCADE,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER,
  mock_test_id INTEGER NOT NULL,
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  submitted_at TEXT,
  score REAL,
  max_score REAL,
  correct_count INTEGER,
  incorrect_count INTEGER,
  unanswered_count INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, attempt_number INTEGER, elapsed_seconds INTEGER NOT NULL DEFAULT 0, save_count INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE SET NULL,
  FOREIGN KEY (mock_test_id)
    REFERENCES education_mock_tests(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_attempt_answers (
  attempt_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  selected_answer TEXT,
  correct INTEGER
    CHECK (correct IS NULL OR correct IN (0,1)),
  marks_awarded REAL, marked_for_review INTEGER NOT NULL DEFAULT 0
  CHECK (marked_for_review IN (0,1)),
  PRIMARY KEY (attempt_id, question_id),
  FOREIGN KEY (attempt_id)
    REFERENCES education_mock_attempts(id)
    ON DELETE CASCADE,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE RESTRICT
);
CREATE TABLE education_mock_question_answers (
  question_id INTEGER PRIMARY KEY,
  answer_key TEXT NOT NULL,
  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
CREATE TABLE education_student_question_history (
  student_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  first_attempted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (
    student_id,
    question_id
  ),

  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,

  FOREIGN KEY (question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
) WITHOUT ROWID;
CREATE TABLE education_protection_milestones (
  student_id INTEGER PRIMARY KEY,

  milestone_25_shown INTEGER NOT NULL DEFAULT 0
    CHECK (milestone_25_shown IN (0,1)),

  milestone_50_shown INTEGER NOT NULL DEFAULT 0
    CHECK (milestone_50_shown IN (0,1)),

  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE
);
CREATE TABLE education_teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  gyan_account_id INTEGER,
  teacher_name TEXT NOT NULL,
  email TEXT NOT NULL COLLATE NOCASE,
  subjects TEXT NOT NULL DEFAULT '',
  location TEXT,
  bio TEXT,
  status TEXT NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING','APPROVED','INACTIVE')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(email),
  FOREIGN KEY (gyan_account_id)
    REFERENCES gyan_accounts(id)
    ON DELETE SET NULL
);
CREATE TABLE education_teacher_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL,
  teacher_id INTEGER,
  status TEXT NOT NULL DEFAULT 'REQUESTED'
    CHECK (status IN ('REQUESTED','ASSIGNED','CLOSED')),
  requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  assigned_at TEXT,
  assigned_by_email TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, request_email TEXT, request_phone TEXT, request_subjects TEXT,
  FOREIGN KEY (student_id)
    REFERENCES education_students(id)
    ON DELETE CASCADE,
  FOREIGN KEY (teacher_id)
    REFERENCES education_teachers(id)
    ON DELETE SET NULL
);
CREATE TABLE education_countries (
  country_code TEXT PRIMARY KEY,
  country_name TEXT NOT NULL,
  flag_emoji TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_program_catalog (
  program_code TEXT PRIMARY KEY,
  canonical_name TEXT NOT NULL,

  /*
   * Grade/catalog key used by education_subjects/topics/questions.
   * Examples:
   * PROGRAM_JEE
   * PROGRAM_NEET
   * PROGRAM_SAT
   */
  grade_code TEXT NOT NULL,

  /*
   * Reusable UI/engine family.
   * Examples: CBT, ABILITY, ABA
   */
  experience_type TEXT NOT NULL DEFAULT 'CBT',

  enabled INTEGER NOT NULL DEFAULT 1,

  show_questions INTEGER NOT NULL DEFAULT 1,
  show_mock_tests INTEGER NOT NULL DEFAULT 0,
  show_reports INTEGER NOT NULL DEFAULT 1,
  show_demo INTEGER NOT NULL DEFAULT 0,
  show_classes INTEGER NOT NULL DEFAULT 0,

  duration_minutes INTEGER,
  question_count INTEGER,

  correct_marks REAL,
  incorrect_marks REAL,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE education_sat_question_details (
  question_id INTEGER PRIMARY KEY,

  response_type TEXT NOT NULL DEFAULT 'MCQ'
    CHECK (response_type IN ('MCQ','SPR')),

  stimulus_type TEXT NOT NULL DEFAULT 'NONE'
    CHECK (stimulus_type IN (
      'NONE',
      'TEXT',
      'PASSAGE_PAIR',
      'STUDENT_NOTES',
      'TABLE',
      'BAR_GRAPH',
      'LINE_GRAPH',
      'OTHER_GRAPHIC'
    )),

  stimulus_text TEXT,
  stimulus_secondary_text TEXT,

  -- JSON payload for a table/graph or future structured visual.
  stimulus_data_json TEXT,

  -- For Math student-produced response questions.
  accepted_answers_json TEXT,

  -- SAT section/module metadata. NULL means usable in either module.
  module_number INTEGER
    CHECK (module_number IS NULL OR module_number IN (1,2)),

  module_path TEXT
    CHECK (
      module_path IS NULL OR
      module_path IN ('BASE','EASIER','HARDER')
    ),

  calculator_allowed INTEGER NOT NULL DEFAULT 1
    CHECK (calculator_allowed IN (0,1)),

  contextual INTEGER NOT NULL DEFAULT 0
    CHECK (contextual IN (0,1)),

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY(question_id)
    REFERENCES education_questions(id)
    ON DELETE CASCADE
);
